Implement the Verilog module based on the following description.
Build an 8-bit bidirectional shift register with synchronous active high reset signal and direction control signal.
// (1) reset: Resets the shift register to 8'b00000000.
// (2) dir: Direction control (1 for left, 0 for right).
// (3) d: Data input to be shifted in.
// (4) q: The value of the shift register.

module top_module(
    input clk,
    input reset,
    input dir,
    input d,
    output reg [7:0] q);

code:
module top_module(
    input clk,
    input reset,
    input dir,
    input d,
    output reg [7:0] q
);

    always @(posedge clk) begin
        if (reset) begin
            // Synchronous reset: Reset the shift register to 8'b00000000
            q <= 8'b00000000;
        end else if (dir) begin
            // Shift left
            q <= {q[6:0], d};
        end else begin
            // Shift right
            q <= {d, q[7:1]};
        end
    end

endmodule

