module top_module(
	input clk,
	input send,
	input [7:0] data,
	output tx,
	output ready
);reg [7:0] bit_count;
	reg [10:0] msg;

	reg r_tx; 
	reg r_ready; 

	initial begin
		bit_count 	<= 0;
		msg 		<= 0;
		r_tx 		<= 0;
		r_ready 	<= 0;
	end

	always @(posedge clk) begin
		if(send && !msg) begin
			// add start bit and stop bit + pause
			msg <= {2'b11, data, 1'b0}; 
			bit_count <= 10;
		end
		if(msg && bit_count > 0) begin
			r_tx <= msg[0];
			msg  <= msg >> 1;
			bit_count <= bit_count - 1;
		end
		if(bit_count == 0) begin
			r_tx <= 1;
			r_ready <= 1;
		end
		if(!send) begin
			msg <= 0;
			bit_count <= 0;
			r_ready <= 0;
		end
	end

	assign tx = r_tx;
	assign ready = r_ready;

endmodule

