    output reg Y0,
    output reg Y1
);reg [3:0] A_reg, B_reg, C_reg, D_reg;
reg [1:0] stage;

always @(posedge clk) begin
    case (stage)
        0: begin
            A_reg <= A;
            B_reg <= B;
            C_reg <= C;
            D_reg <= D;
            Y0 <= 0;
            Y1 <= 0;
            stage <= 1;
