module top_module(
  input clk,
  input rst_n,
  input a,
  output reg rise,
  output reg fall,
  output reg [31:0] duration  // Change this line to declare `duration` as reg
);reg a_prev;
  reg [31:0] rise_time;
  reg [31:0] fall_time;

  always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      a_prev <= 1'b0;
      rise <= 1'b0;
      fall <= 1'b0;
      duration <= 32'h0;
      rise_time <= 32'h0;
      fall_time <= 32'h0;
    end
    else begin
      if (a == 1'b1 && a_prev == 1'b0) begin
        rise <= 1'b1;
        rise_time <= $time;
      end
      else begin
        rise <= 1'b0;
      end

      if (a == 1'b0 && a_prev == 1'b1) begin
        fall <= 1'b1;
        fall_time <= $time;
      end
      else begin
        fall <= 1'b0;
      end

      if (rise_time != 32'h0 && fall_time != 32'h0) begin
        duration <= fall_time - rise_time;
      end
    end

    a_prev <= a; // Move this outside the always block's if-else structure to avoid reconvergence 
  end

endmodule

module d_flipflop (D, CLK, RST, EN, Q);
input D, CLK, RST, EN;
output reg Q;

always @(posedge CLK or posedge RST) begin
    if (RST) begin
        Q <= 1'b0;
    end
    else if (EN) begin
        Q <= D;
    end
end

endmodule

