description:
Implement a synchronizer circuit that ensures safe transfer of an asynchronous input signal (data_in) into a clocked domain. The module employs a dual flip-flop design to mitigate metastability issues, capturing the data input on the rising edge of the clock (clk) and updating the synchronized output (data_out). The circuit resets the synchronization process when the active high reset signal (rst) is triggered, initializing the output to a known state (00). This design is crucial for reliable interfacing between different clock domains.
module top_module(

// OUTPUTs
    data_out,                      // Synchronized data output

// INPUTs
    clk,                           // Receiving clock
    data_in,                       // Asynchronous data input
    rst                            // Receiving reset (active high)
);

code:
module top_module(

// OUTPUTs
    data_out,                      // Synchronized data output

// INPUTs
    clk,                           // Receiving clock
    data_in,                       // Asynchronous data input
    rst                            // Receiving reset (active high)
);// OUTPUTs
//=========
output              data_out;      // Synchronized data output

// INPUTs
//=========
input               clk;          // Receiving clock
input               data_in;      // Asynchronous data input
input               rst;          // Receiving reset (active high)


//=============================================================================
// 1)  SYNCHRONIZER
//=============================================================================

reg  [1:0] data_sync;

always @(posedge clk or posedge rst)
  if (rst) data_sync <=  2'b00;
  else     data_sync <=  {data_sync[0], data_in};

assign     data_out   =   data_sync[1];


endmodule

