   input [2:0] addr,
   output reg [7:0] we
);always @*
   case({write, datamode, addr})
      // Byte
      {1'b1, 2'b00, 3'b000} : we = 8'b00000001;
      {1'b1, 2'b00, 3'b001} : we = 8'b00000010;
      {1'b1, 2'b00, 3'b010} : we = 8'b00000100;
      {1'b1, 2'b00, 3'b011} : we = 8'b00001000;
      {1'b1, 2'b00, 3'b100} : we = 8'b00010000;
      {1'b1, 2'b00, 3'b101} : we = 8'b00100000;
      {1'b1, 2'b00, 3'b110} : we = 8'b01000000;
      {1'b1, 2'b00, 3'b111} : we = 8'b10000000;
      // Short
      {1'b1, 2'b01, 2'bxx} : we = 8'b00000011; // This should match addr[1:0]
      {1'b1, 2'b10, 2'bxx} : we = 8'b00110000; // This should match addr[1:0]
      {1'b1, 2'b11, 2'bxx} : we = 8'b11000000; // This should match addr[1:0]
      // Word
      {1'b1, 2'b10, 2'bxx} : we = 8'b00001111; // This part should also match with addr[1:0]
      {1'b1, 2'b11, 2'bxx} : we = 8'b11110000; // This part should also match with addr[1:0]
      // Double
      {1'b1, 2'b11, 2'bxx} : we = 8'b11111111; // This part should also match with addr[1:0]
      default : we = 8'b00000000;
   endcase

