module fsm (
        input clk,
        input reset,
        input w,
        output reg y);parameter P0=0, P1=1, P2=2;
	reg [1:0] state, next;

	always @(posedge clk)
		if (reset)
			state <= P0;
		else 
			state <= next;


	always_comb begin
		case(state)
			P0: next = w ? P1 : P2;
			P1: next = w ? P2 : P0;
			P2: next = w ? P0 : P1;
			default: next = 'x;
		endcase
	end

	assign y = (state == P1 || state == P2);

endmodule

