description:
Design a 4-bit circular shift register that captures the input value on the rising edge of the clock and stores it in a buffer. The buffer can hold up to four values, and the output will always reflect the most recently stored value based on the current position pointer, which wraps around when it exceeds three, effectively creating a circular data structure.
module top_module(
    input clk,
    input [3:0] in,
    output reg [3:0] out
);

code:
module top_module(
    input clk,
    input [3:0] in,
    output reg [3:0] out
);reg [3:0] buffer [0:3];
reg [1:0] ptr = 0;

always @(posedge clk) begin
    buffer[ptr] <= in;
    ptr <= (ptr == 3) ? 0 : ptr + 1;
end

always @(posedge clk) begin
    out <= buffer[ptr];
end

endmodule

